CREATE TABLE IF NOT EXISTS users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(190) UNIQUE NOT NULL,hash VARCHAR(255) NOT NULL,role ENUM('participant','admin','staff') NOT NULL DEFAULT 'participant');
CREATE TABLE IF NOT EXISTS events(id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(150) NOT NULL,genre VARCHAR(40) NOT NULL,venue VARCHAR(160) NOT NULL,starts DATETIME NOT NULL,description TEXT NOT NULL,art ENUM('concert','conference','art') NOT NULL, INDEX(starts));
CREATE TABLE IF NOT EXISTS categories(id INT AUTO_INCREMENT PRIMARY KEY,event_id INT NOT NULL,name VARCHAR(80) NOT NULL,price DECIMAL(10,2) UNSIGNED NOT NULL,capacity INT UNSIGNED NOT NULL,numbered BOOLEAN NOT NULL DEFAULT 0,FOREIGN KEY(event_id) REFERENCES events(id) ON DELETE CASCADE, UNIQUE(event_id,name));
CREATE TABLE IF NOT EXISTS bookings(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,category_id INT NOT NULL,created DATETIME NOT NULL,request_key CHAR(32) UNIQUE NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(category_id) REFERENCES categories(id));
CREATE TABLE IF NOT EXISTS payments(booking_id INT PRIMARY KEY,amount DECIMAL(10,2) UNSIGNED NOT NULL,paid_at DATETIME NULL,FOREIGN KEY(booking_id) REFERENCES bookings(id));
CREATE TABLE IF NOT EXISTS tickets(id INT AUTO_INCREMENT PRIMARY KEY,booking_id INT UNIQUE NOT NULL,category_id INT NOT NULL,seat INT NULL,code CHAR(24) UNIQUE NOT NULL,UNIQUE(category_id,seat),FOREIGN KEY(booking_id) REFERENCES bookings(id),FOREIGN KEY(category_id) REFERENCES categories(id));
CREATE TABLE IF NOT EXISTS attendance(ticket_id INT PRIMARY KEY,staff_id INT NOT NULL,checked DATETIME NOT NULL,FOREIGN KEY(ticket_id) REFERENCES tickets(id),FOREIGN KEY(staff_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS event_covers(event_id INT PRIMARY KEY,jpeg MEDIUMBLOB NOT NULL,FOREIGN KEY(event_id) REFERENCES events(id) ON DELETE CASCADE);
